preConditionHook:
// THE THREE-PUSH PATTERN -- Brooks's wedge / three-push / expanding triangle,
// read as three successive CONFIRMED swing pivots on the same side, each one
// extending further than the last. LONG is a three-push BOTTOM (three
// successively lower swing lows -- the bull setup); SHORT is a three-push TOP.
// This is the base of the B03 family; the other rules carry their own copy of
// the scan below, because rules in this corpus never reference each other.
//
// THE PIVOT SCAN IS INLINED rather than leaning on SwingLow(1/2/3, ...) in the
// twin: the register's swinghigh row lists Occurrence 3 and above as
// UNMEASURED, so the third push -- the whole point of the pattern -- would
// otherwise rest on an untested argument. The scan reproduces the MEASURED
// pivot test exactly (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60 min):
//   * the pivot bar is AT OR ABOVE the `swingStrength` OLDER bars and STRICTLY
//     ABOVE the `swingStrength` NEWER bars, so a flat top yields exactly ONE
//     pivot, the LATER of the equal bars. Bars-ago indexing means the SMALLER
//     index is the NEWER bar, so the strict half is the k < j loop (el_gt) and
//     the at-or-above half the k > j loop (el_ge);
//   * the confirmation lag is exactly `swingStrength` bars, which is why the
//     scan starts at j = swingStrength and never at 0 -- that lag is what
//     makes the rule lookahead-safe;
//   * candidate offsets run 0 .. Length - 1 from the current bar INCLUSIVE, so
//     j stops at lookbackBars - 1, while the neighbourhood test reaches
//     `swingStrength` bars PAST the window: the deepest bar touched is
//     lookbackBars - 1 + swingStrength;
//   * scanning newest-first and recording the first three hits reproduces
//     Occurrence 1, 2, 3;
//   * the comparisons carry the 2.22e-12 relational tolerance, hence el_gt /
//     el_ge / el_lt / el_le rather than raw > and >=;
//   * the prices are initialised to the -1 SENTINEL and every use is gated on
//     the count reaching 3 -- -1 as a price sits under every real price;
//   * the low side's TIE sense is the mirror of the measured high-side rule
//     rather than an observation, as the swinglow row records.
// There is no WFSafe_SwingHigh in the MultiWalk library, so plain EL governs.
// Written WITHOUT an early `break`, matching the EL twin statement for
// statement: Break is not a registered EasyLanguage word, so the twin's loops
// run to the end and the `< 3` guards stop a fourth pivot being recorded.
//
// shapeMode selects the SHAPE: 0 = any three pushes, 1 = CONVERGING, each push
// extending less than the one before (Brooks's wedge), 2 = EXPANDING, each
// push extending more (the expanding triangle). The extents are raw price
// differences; the per-bar (slope) reading of the same two increments is
// ThreePushAcceleration, a separate pane. shapeMode is an integer selector,
// compared exactly rather than through el_eq -- it is not a price.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivStrength = (int)swingStrength;
pivWindow = (int)lookbackBars;
mode = (int)shapeMode;
nHiPiv = 0;
nLoPiv = 0;
hiPx1 = -1.0;
hiPx2 = -1.0;
hiPx3 = -1.0;
loPx1 = -1.0;
loPx2 = -1.0;
loPx3 = -1.0;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivStrength; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHiPiv < 3) {
        nHiPiv = nHiPiv + 1;
        if (nHiPiv == 1) hiPx1 = high[j];
        if (nHiPiv == 2) hiPx2 = high[j];
        if (nHiPiv == 3) hiPx3 = high[j];
    }
    if (okLo && nLoPiv < 3) {
        nLoPiv = nLoPiv + 1;
        if (nLoPiv == 1) loPx1 = low[j];
        if (nLoPiv == 2) loPx2 = low[j];
        if (nLoPiv == 3) loPx3 = low[j];
    }
}
patUp = (nHiPiv == 3) && el_gt(hiPx1, hiPx2) && el_gt(hiPx2, hiPx3);
patDn = (nLoPiv == 3) && el_lt(loPx1, loPx2) && el_lt(loPx2, loPx3);
upLate = hiPx1 - hiPx2;
upEarly = hiPx2 - hiPx3;
dnLate = loPx2 - loPx1;
dnEarly = loPx3 - loPx2;
shapeOkUp = (mode == 0) || ((mode == 1) && el_lt(upLate, upEarly)) || ((mode == 2) && el_gt(upLate, upEarly));
shapeOkDn = (mode == 0) || ((mode == 1) && el_lt(dnLate, dnEarly)) || ((mode == 2) && el_gt(dnLate, dnEarly));
